"use strict";(globalThis.webpackChunktesting_knowledge_base=globalThis.webpackChunktesting_knowledge_base||[]).push([[849],{6164(e){e.exports=JSON.parse('{"version":{"pluginId":"default","version":"current","label":"Next","banner":null,"badge":false,"noIndex":false,"className":"docs-version-current","isLast":true,"docsSidebars":{"jmeterSidebar":[{"type":"category","label":"Apache JMeter","collapsible":false,"items":[{"type":"category","label":"Basics","collapsible":false,"items":[{"type":"link","href":"/docs/jmeter/01-install-tools","label":"Install Tools","docId":"jmeter/01-install-tools","unlisted":false},{"type":"link","href":"/docs/jmeter/02-understand-requirements","label":"Understand Requirements and Flow","docId":"jmeter/02-understand-requirements","unlisted":false},{"type":"link","href":"/docs/jmeter/03-jmeter-elements","label":"JMeter Elements Overview","docId":"jmeter/03-jmeter-elements","unlisted":false},{"type":"category","label":"Recording","collapsed":false,"items":[{"type":"link","href":"/docs/jmeter/04-recording","label":"Recording with BlazeMeter + Fiddler","docId":"jmeter/04-recording","unlisted":false},{"type":"link","href":"/docs/jmeter/04a-recording-mitmproxy","label":"Recording with BlazeMeter + mitmproxy","docId":"jmeter/04a-recording-mitmproxy","unlisted":false}],"collapsible":true},{"type":"link","href":"/docs/jmeter/05-correlation-parameterization","label":"Correlation and Parameterization","docId":"jmeter/05-correlation-parameterization","unlisted":false},{"type":"link","href":"/docs/jmeter/06-script-enhancement","label":"Script Enhancement","docId":"jmeter/06-script-enhancement","unlisted":false},{"type":"link","href":"/docs/jmeter/07-debug","label":"Debug","docId":"jmeter/07-debug","unlisted":false}],"collapsed":false},{"type":"category","label":"Applying Load","collapsible":false,"items":[{"type":"link","href":"/docs/jmeter/08-load-model","label":"Design Load Model","docId":"jmeter/08-load-model","unlisted":false},{"type":"link","href":"/docs/jmeter/09-execute-analyze","label":"Execute and Analyze Results","docId":"jmeter/09-execute-analyze","unlisted":false},{"type":"link","href":"/docs/jmeter/10-reporting","label":"Reporting","docId":"jmeter/10-reporting","unlisted":false}],"collapsed":false},{"type":"category","label":"Advanced","collapsible":false,"items":[{"type":"link","href":"/docs/jmeter/11-backend-listener","label":"Backend Listener - InfluxDB + Grafana","docId":"jmeter/11-backend-listener","unlisted":false},{"type":"link","href":"/docs/jmeter/12-distributed-testing","label":"Distributed Testing","docId":"jmeter/12-distributed-testing","unlisted":false},{"type":"link","href":"/docs/jmeter/13-distributed-testing-hands-on","label":"Try Distributed Testing on Your Own Machine","docId":"jmeter/13-distributed-testing-hands-on","unlisted":false},{"type":"link","href":"/docs/jmeter/14-test-data-python","label":"Test Data Preparation with Python","docId":"jmeter/14-test-data-python","unlisted":false},{"type":"link","href":"/docs/jmeter/15-automation-batch","label":"Automation with Batch Files","docId":"jmeter/15-automation-batch","unlisted":false}],"collapsed":false},{"type":"category","label":"Appendix","collapsible":false,"items":[{"type":"link","href":"/docs/jmeter/99-future-to-explore","label":"Future / To Explore","docId":"jmeter/99-future-to-explore","unlisted":false},{"type":"link","href":"/docs/jmeter/99-archive-oci-linux-slave-setup","label":"OCI Linux Slave Setup (Archived)","docId":"jmeter/99-archive-oci-linux-slave-setup","unlisted":false}],"collapsed":false}],"collapsed":false,"href":"/docs/jmeter/"}],"loadlitmusSidebar":[{"type":"category","label":"LoadLitmus","collapsible":false,"items":[{"type":"category","label":"Basics","collapsible":false,"items":[{"type":"link","href":"/docs/loadlitmus/01-what-is-loadlitmus","label":"What LoadLitmus Is","docId":"loadlitmus/01-what-is-loadlitmus","unlisted":false},{"type":"link","href":"/docs/loadlitmus/02-install-and-first-project","label":"Install and First Project","docId":"loadlitmus/02-install-and-first-project","unlisted":false},{"type":"link","href":"/docs/loadlitmus/03-script-requirements","label":"Script Requirements","docId":"loadlitmus/03-script-requirements","unlisted":false}],"collapsed":false},{"type":"category","label":"Running Tests","collapsible":false,"items":[{"type":"link","href":"/docs/loadlitmus/04-running-a-test","label":"Running a Test","docId":"loadlitmus/04-running-a-test","unlisted":false},{"type":"link","href":"/docs/loadlitmus/05-results-and-monitoring","label":"Results and Monitoring","docId":"loadlitmus/05-results-and-monitoring","unlisted":false},{"type":"link","href":"/docs/loadlitmus/06-fleet-and-distributed","label":"Fleet and Distributed Runs","docId":"loadlitmus/06-fleet-and-distributed","unlisted":false}],"collapsed":false},{"type":"category","label":"Appendix","collapsible":false,"items":[{"type":"link","href":"/docs/loadlitmus/99-script-template","label":"Starter Script Template","docId":"loadlitmus/99-script-template","unlisted":false}],"collapsed":false}],"collapsed":false,"href":"/docs/loadlitmus/"}],"playgroundSidebar":[{"type":"category","label":"Playground","collapsible":false,"items":[{"type":"category","label":"Basics","collapsible":false,"items":[{"type":"link","href":"/docs/playground/01-run-locally","label":"Run It Locally","docId":"playground/01-run-locally","unlisted":false},{"type":"link","href":"/docs/playground/02-testing-against-it","label":"Testing Against It","docId":"playground/02-testing-against-it","unlisted":false}],"collapsed":false}],"collapsed":false,"href":"/docs/playground/"}],"playwrightSidebar":[{"type":"category","label":"Playwright","collapsible":false,"items":[{"type":"category","label":"Basics","collapsible":false,"items":[{"type":"link","href":"/docs/playwright/01-install-tools","label":"Install Tools","docId":"playwright/01-install-tools","unlisted":false},{"type":"link","href":"/docs/playwright/02-what-to-automate","label":"Understand What to Automate","docId":"playwright/02-what-to-automate","unlisted":false},{"type":"link","href":"/docs/playwright/03-playwright-concepts","label":"Playwright Concepts","docId":"playwright/03-playwright-concepts","unlisted":false},{"type":"link","href":"/docs/playwright/04-recording-with-codegen","label":"Recording with Codegen","docId":"playwright/04-recording-with-codegen","unlisted":false},{"type":"link","href":"/docs/playwright/05-locators-and-assertions","label":"Locators and Assertions","docId":"playwright/05-locators-and-assertions","unlisted":false},{"type":"link","href":"/docs/playwright/06-test-structure-and-page-objects","label":"Test Structure and Page Objects","docId":"playwright/06-test-structure-and-page-objects","unlisted":false},{"type":"link","href":"/docs/playwright/07-debug","label":"Debug","docId":"playwright/07-debug","unlisted":false}],"collapsed":false},{"type":"category","label":"Running","collapsible":false,"items":[{"type":"link","href":"/docs/playwright/08-configuration-and-running","label":"Configuration and Running","docId":"playwright/08-configuration-and-running","unlisted":false},{"type":"link","href":"/docs/playwright/09-authentication-and-state","label":"Authentication and State","docId":"playwright/09-authentication-and-state","unlisted":false},{"type":"link","href":"/docs/playwright/10-running-in-ci","label":"Running in CI","docId":"playwright/10-running-in-ci","unlisted":false}],"collapsed":false},{"type":"category","label":"Appendix","collapsible":false,"items":[{"type":"link","href":"/docs/playwright/99-future-to-explore","label":"Future / To Explore","docId":"playwright/99-future-to-explore","unlisted":false}],"collapsed":false}],"collapsed":false,"href":"/docs/playwright/"}],"performanceTestingSidebar":[{"type":"category","label":"Performance Testing","collapsible":false,"items":[{"type":"category","label":"Basics","collapsible":false,"items":[{"type":"link","href":"/docs/performance-testing/01-fundamentals","label":"Performance Testing Fundamentals","docId":"performance-testing/01-fundamentals","unlisted":false}],"collapsed":false},{"type":"category","label":"Mapping to Tools","collapsible":false,"items":[{"type":"link","href":"/docs/performance-testing/02-mapping-to-jmeter","label":"Mapping to JMeter","docId":"performance-testing/02-mapping-to-jmeter","unlisted":false},{"type":"link","href":"/docs/performance-testing/03-mapping-to-k6","label":"Mapping to k6","docId":"performance-testing/03-mapping-to-k6","unlisted":false}],"collapsed":false}],"collapsed":false,"href":"/docs/performance-testing/"}]},"docs":{"jmeter/01-install-tools":{"id":"jmeter/01-install-tools","title":"Install Tools","description":"Before starting performance testing, you need the following tools set up on your machine.","sidebar":"jmeterSidebar"},"jmeter/02-understand-requirements":{"id":"jmeter/02-understand-requirements","title":"Understand Requirements and Flow","description":"Before opening JMeter, you need to understand what you are testing and why. Skipping this step leads to wasted effort - building scripts for the wrong flows or testing with unrealistic numbers.","sidebar":"jmeterSidebar"},"jmeter/03-jmeter-elements":{"id":"jmeter/03-jmeter-elements","title":"JMeter Elements Overview","description":"Before you start recording and building scripts, you need to understand the building blocks of JMeter. This section covers the elements you\'ll use most often and how they relate to each other.","sidebar":"jmeterSidebar"},"jmeter/04-recording":{"id":"jmeter/04-recording","title":"Recording with BlazeMeter + Fiddler","description":"This section covers how to record your test script using both Fiddler and Blazemeter simultaneously. This dual-recording approach gives you the best of both tools.","sidebar":"jmeterSidebar"},"jmeter/04a-recording-mitmproxy":{"id":"jmeter/04a-recording-mitmproxy","title":"Recording with BlazeMeter + mitmproxy","description":"This page is the dual recording workflow with mitmproxy in place of Fiddler Classic. It works on macOS and Windows. The only change is the evidence-capture tool. BlazeMeter stays exactly as it is in Section 4 - Recording.","sidebar":"jmeterSidebar"},"jmeter/05-correlation-parameterization":{"id":"jmeter/05-correlation-parameterization","title":"Correlation and Parameterization","description":"After recording, the script has hardcoded values everywhere - tokens, session IDs, timestamps, and other dynamic values that change every session. The script will fail on replay if these are not handled. This step makes the script dynamic.","sidebar":"jmeterSidebar"},"jmeter/06-script-enhancement":{"id":"jmeter/06-script-enhancement","title":"Script Enhancement","description":"After correlation and parameterization, the script works but it\'s messy - auto-generated names, flat structure, no validation. This step turns it into a clean, maintainable, and robust test plan.","sidebar":"jmeterSidebar"},"jmeter/07-debug":{"id":"jmeter/07-debug","title":"Debug","description":"After enhancing the script with transaction controllers, assertions, extractors, and timers, you need to verify it actually works end-to-end before running any load. Debugging is about running the script with a single user and making sure every request succeeds, every extraction works, and every assertion passes.","sidebar":"jmeterSidebar"},"jmeter/08-load-model":{"id":"jmeter/08-load-model","title":"Design Load Model","description":"The script works with 1 user - now you need to define how to apply load. The load model determines how many users, how fast they ramp up, how long the test runs, and what the pacing looks like. All of this comes from the requirements gathered in Section 2.","sidebar":"jmeterSidebar"},"jmeter/09-execute-analyze":{"id":"jmeter/09-execute-analyze","title":"Execute and Analyze Results","description":"The script is debugged, the load model is defined - now it\'s time to run the actual load test and make sense of the results. Always run load tests in CLI mode (command line), never from the GUI.","sidebar":"jmeterSidebar"},"jmeter/10-reporting":{"id":"jmeter/10-reporting","title":"Reporting","description":"You have the results - now you need to communicate them. The report should be clear enough for both technical and non-technical stakeholders to understand whether the system passed or failed.","sidebar":"jmeterSidebar"},"jmeter/11-backend-listener":{"id":"jmeter/11-backend-listener","title":"Backend Listener - InfluxDB + Grafana","description":"The JMeter web report is generated after the test finishes. If you want to monitor results in real-time while the test is running, you need a Backend Listener that streams data to InfluxDB, which Grafana then visualizes as a live dashboard.","sidebar":"jmeterSidebar"},"jmeter/12-distributed-testing":{"id":"jmeter/12-distributed-testing","title":"Distributed Testing","description":"When a single machine can\'t generate enough load (CPU or memory maxes out before reaching the target thread count), you distribute the load across multiple machines. JMeter has built-in support for this using a controller-worker architecture.","sidebar":"jmeterSidebar"},"jmeter/13-distributed-testing-hands-on":{"id":"jmeter/13-distributed-testing-hands-on","title":"Try Distributed Testing on Your Own Machine","description":"Section 12 covers the theory of distributed testing - controller, workers, RMI, and the many things that can go wrong between them. This section is where you actually do it, end to end, on hardware you already own.","sidebar":"jmeterSidebar"},"jmeter/14-test-data-python":{"id":"jmeter/14-test-data-python","title":"Test Data Preparation with Python","description":"When running distributed tests with unique data per user, you need to split CSV files so each worker machine gets a different subset. Python makes this quick and repeatable.","sidebar":"jmeterSidebar"},"jmeter/15-automation-batch":{"id":"jmeter/15-automation-batch","title":"Automation with Batch Files","description":"Manually starting jmeter-server on each worker, copying files, and running the test gets repetitive fast - especially when you have multiple machines and run tests frequently. Batch files automate these steps.","sidebar":"jmeterSidebar"},"jmeter/99-archive-oci-linux-slave-setup":{"id":"jmeter/99-archive-oci-linux-slave-setup","title":"OCI Linux Slave Setup (Archived)","description":"Archived: This guide is kept for reference, not as the recommended path. To learn distributed testing hands-on, use Try Distributed Testing on Your Own Machine instead - it teaches the same workflow with free local VMs and no cloud account. Come back here when you specifically need Oracle Cloud, and be aware the OCI console and free-tier terms may have changed since this was written.","sidebar":"jmeterSidebar"},"jmeter/99-future-to-explore":{"id":"jmeter/99-future-to-explore","title":"Future / To Explore","description":"Topics not covered in this guide but worth exploring as you advance.","sidebar":"jmeterSidebar"},"jmeter/index":{"id":"jmeter/index","title":"Performance Testing with JMeter","description":"A practical guide on how to approach performance testing using JMeter \u2014 from setup to automation.","sidebar":"jmeterSidebar"},"loadlitmus/01-what-is-loadlitmus":{"id":"loadlitmus/01-what-is-loadlitmus","title":"What LoadLitmus Is","description":"What the LoadLitmus dashboard does, what it deliberately does not do, and when to use it instead of running JMeter by hand.","sidebar":"loadlitmusSidebar"},"loadlitmus/02-install-and-first-project":{"id":"loadlitmus/02-install-and-first-project","title":"Install and First Project","description":"Installing LoadLitmus, where its data folder lives, creating your first project, and the ports and access rules you need to know.","sidebar":"loadlitmusSidebar"},"loadlitmus/03-script-requirements":{"id":"loadlitmus/03-script-requirements","title":"Script Requirements","description":"What a JMeter .jmx file needs so LoadLitmus can drive its load, data and results - and which thread-group shapes turn features off.","sidebar":"loadlitmusSidebar"},"loadlitmus/04-running-a-test":{"id":"loadlitmus/04-running-a-test","title":"Running a Test","description":"The Runner page end to end - selecting a plan, setting load, parameters and data, watching the live log, stopping safely, and copying the run into CI.","sidebar":"loadlitmusSidebar"},"loadlitmus/05-results-and-monitoring":{"id":"loadlitmus/05-results-and-monitoring","title":"Results and Monitoring","description":"Reading a finished run in LoadLitmus - metrics, HTML reports, comparisons, exports and auto-analysis - plus live monitoring through InfluxDB.","sidebar":"loadlitmusSidebar"},"loadlitmus/06-fleet-and-distributed":{"id":"loadlitmus/06-fleet-and-distributed","title":"Fleet and Distributed Runs","description":"Running load from several machines with LoadLitmus Fleet - slaves over SSH, provisioning, ports, distributing test data and collecting failed responses.","sidebar":"loadlitmusSidebar"},"loadlitmus/99-script-template":{"id":"loadlitmus/99-script-template","title":"Starter Script Template","description":"A ready-made JMeter .jmx skeleton built for LoadLitmus - download it, fill in the placeholders, and start a project with the Load card, guards and portable paths already wired up.","sidebar":"loadlitmusSidebar"},"loadlitmus/index":{"id":"loadlitmus/index","title":"LoadLitmus","description":"A practical guide to LoadLitmus, the on-premise web dashboard we use to run, store and report JMeter performance tests.","sidebar":"loadlitmusSidebar"},"performance-testing/01-fundamentals":{"id":"performance-testing/01-fundamentals","title":"Performance Testing Fundamentals","description":"What performance testing is, where it sits in the testing family, and how load, stress, spike, endurance and scalability tests differ.","sidebar":"performanceTestingSidebar"},"performance-testing/02-mapping-to-jmeter":{"id":"performance-testing/02-mapping-to-jmeter","title":"Mapping to JMeter","description":"How to run smoke, load, stress, endurance, spike and scalability tests from one JMeter test plan.","sidebar":"performanceTestingSidebar"},"performance-testing/03-mapping-to-k6":{"id":"performance-testing/03-mapping-to-k6","title":"Mapping to k6","description":"How to run smoke, load, stress, endurance, spike and scalability tests from one k6 script.","sidebar":"performanceTestingSidebar"},"performance-testing/index":{"id":"performance-testing/index","title":"Performance Testing","description":"What performance testing is and how each test type is set up, before you pick a tool. Start here, then go to the JMeter or k6 guide.","sidebar":"performanceTestingSidebar"},"playground/01-run-locally":{"id":"playground/01-run-locally","title":"Run It Locally","description":"Start the Pizza Playground on your own machine with Docker Compose.","sidebar":"playgroundSidebar"},"playground/02-testing-against-it":{"id":"playground/02-testing-against-it","title":"Testing Against It","description":"Accounts, reset, load-test switches, UI test ids and the API map for the Pizza Playground.","sidebar":"playgroundSidebar"},"playground/index":{"id":"playground/index","title":"Playground","description":"The Pizza Playground, a Docker-based pizza ordering app we use as the target for JMeter, k6 and Playwright practice.","sidebar":"playgroundSidebar"},"playwright/01-install-tools":{"id":"playwright/01-install-tools","title":"Install Tools","description":"Before writing any UI test, you need Node, an editor with the Playwright extension, and a Playwright project with browsers downloaded. This page gets you from nothing to a green test run.","sidebar":"playwrightSidebar"},"playwright/02-what-to-automate":{"id":"playwright/02-what-to-automate","title":"Understand What to Automate","description":"UI tests are the most expensive tests to write and the slowest to run. Before recording anything, decide which flows deserve one. This is the same thinking as understanding requirements for a performance test: the tool comes after the plan.","sidebar":"playwrightSidebar"},"playwright/03-playwright-concepts":{"id":"playwright/03-playwright-concepts","title":"Playwright Concepts","description":"Before recording or writing tests, learn the handful of building blocks every Playwright test is made of. This is the JMeter Elements Overview equivalent for UI automation.","sidebar":"playwrightSidebar"},"playwright/04-recording-with-codegen":{"id":"playwright/04-recording-with-codegen","title":"Recording with Codegen","description":"Playwright ships a recorder. You click through the flow in a real browser and it writes the test for you, with locators that follow the recommended priority. This is the Recording step of the JMeter track, with one difference: the recorded output is a starting point you will clean up, not the finished test.","sidebar":"playwrightSidebar"},"playwright/05-locators-and-assertions":{"id":"playwright/05-locators-and-assertions","title":"Locators and Assertions","description":"Locators are how you find things on the page. Assertions are how you prove the flow worked. Get these two right and your tests stop being flaky. This is the correlation step of the UI world: the part that turns a raw recording into something that survives a rerun.","sidebar":"playwrightSidebar"},"playwright/06-test-structure-and-page-objects":{"id":"playwright/06-test-structure-and-page-objects","title":"Test Structure and Page Objects","description":"One recorded test is easy. Twenty tests that share a login form, a product list and a set of test accounts need structure, or every UI change becomes twenty edits. This is the script enhancement step: naming, grouping, and moving shared pieces out of the tests.","sidebar":"playwrightSidebar"},"playwright/07-debug":{"id":"playwright/07-debug","title":"Debug","description":"A test failed. Before touching the code, look at what actually happened in the browser. Playwright records enough that you can usually see the cause in a minute. This is the Debug step of the JMeter track, with better tooling.","sidebar":"playwrightSidebar"},"playwright/08-configuration-and-running":{"id":"playwright/08-configuration-and-running","title":"Configuration and Running","description":"playwright.config.ts is where you decide which browsers run, how many tests run at once, what happens on failure and what gets reported. This page walks through the sample project\'s config line by line, then covers the commands you run every day. It is the load model and execute pages of the JMeter track, for a runner that cares about correctness rather than load.","sidebar":"playwrightSidebar"},"playwright/09-authentication-and-state":{"id":"playwright/09-authentication-and-state","title":"Authentication and State","description":"Most flows start after login. Logging in through the UI in every test is slow and hammers the login endpoint. Playwright\'s answer the session token has to get from the login response into every later request, and here the browser does the carrying.","sidebar":"playwrightSidebar"},"playwright/10-running-in-ci":{"id":"playwright/10-running-in-ci","title":"Running in CI","description":"A UI suite only earns its keep when it runs on every change without anyone remembering to start it. This page wires the sample project into GitHub Actions, keeps the report and traces as artifacts, and shows how to split a slow suite across machines. Concepts carry over to GitLab CI and Azure Pipelines. This is the automation step of the JMeter track.","sidebar":"playwrightSidebar"},"playwright/99-future-to-explore":{"id":"playwright/99-future-to-explore","title":"Future / To Explore","description":"Topics that belong in this track but are not written yet. Each one is a page I plan to add once I have used it on a real project. Until then, the official docs link is the best source.","sidebar":"playwrightSidebar"},"playwright/index":{"id":"playwright/index","title":"UI Automation with Playwright","description":"A practical guide to end-to-end UI testing with Playwright: from install and recording through page objects, authentication and CI. Written in the same order I use on a project.","sidebar":"playwrightSidebar"},"superpowers/specs/2026-09-24-pizza-playground-design":{"id":"superpowers/specs/2026-09-24-pizza-playground-design","title":"Pizza Playground \u2014 Design Spec","description":"Date: 2026-09-24"}}}}')}}]);